class Solution {
public:
    int maxIncreasingCells(vector<vector<int>>& mat) {
        int m = (int)mat.size();
        int n = (int)mat[0].size();
        vector<array<int,3>> cells;
        cells.reserve((size_t)m * n);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                cells.push_back({mat[i][j], i, j});
        sort(cells.begin(), cells.end());
        vector<int> rowMax(m, 0), colMax(n, 0);
        int ans = 0;
        int i = 0;
        int N = (int)cells.size();
        while (i < N) {
            int j = i;
            while (j < N && cells[j][0] == cells[i][0]) j++;
            vector<pair<int,int>> rowUpd, colUpd;
            for (int k = i; k < j; k++) {
                int r = cells[k][1];
                int c = cells[k][2];
                int dp = 1 + max(rowMax[r], colMax[c]);
                if (dp > ans) ans = dp;
                rowUpd.push_back({r, dp});
                colUpd.push_back({c, dp});
            }
            for (auto& p : rowUpd)
                if (p.second > rowMax[p.first]) rowMax[p.first] = p.second;
            for (auto& p : colUpd)
                if (p.second > colMax[p.first]) colMax[p.first] = p.second;
            i = j;
        }
        return ans;
    }
};
